//! Reproducible multi-model experiment orchestration for ADR 0142.
//!
//! The parent runner never benchmarks the user's open project. Every scheduled
//! run receives a fresh repository-owned fixture copy and a fresh Editor child
//! process so authoring, source, validation, Play, proposal, and temporary run
//! state cannot leak into the next model.

use crate::agent_benchmark::{
    benchmark_task, BenchmarkFailureKind, BenchmarkRecord, BenchmarkRunOutcome,
    BenchmarkTaskKind, BENCHMARK_CORPUS_VERSION, BENCHMARK_EXPERIMENT_RUNNER_VERSION,
    BENCHMARK_FIXTURE_VERSION, BENCHMARK_HARNESS_VERSION,
};
use crate::agent_host::{AgentCapability, AgentProposal, AgentWorkClaim};
use crate::resource_arbitration::{QualityPreference, TelemetryValue};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitStatus};
use std::time::{SystemTime, UNIX_EPOCH};

const EXPERIMENT_CONFIG_SCHEMA_VERSION: u32 = 1;
const EXPERIMENT_RESULT_SCHEMA_VERSION: u32 = 1;
const FIXTURE_MARKER_FILE: &str = ".gameengine-agent-benchmark-fixture.json";
const DEFAULT_LOCAL_ENDPOINT: &str = "http://127.0.0.1:11434";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "mode", rename_all = "snake_case")]
pub(crate) enum BenchmarkExecutionOrder {
    Deterministic,
    SeededRandom { seed: u64 },
}

impl Default for BenchmarkExecutionOrder {
    fn default() -> Self {
        Self::Deterministic
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub(crate) struct BenchmarkExperimentConfig {
    pub(crate) schema_version: u32,
    pub(crate) endpoint: String,
    pub(crate) models: Vec<String>,
    pub(crate) tasks: Vec<String>,
    pub(crate) repeat_count: u32,
    pub(crate) quality: QualityPreference,
    pub(crate) execution_order: BenchmarkExecutionOrder,
    pub(crate) stop_on_failure: bool,
    pub(crate) output_dir: PathBuf,
}

impl Default for BenchmarkExperimentConfig {
    fn default() -> Self {
        Self {
            schema_version: EXPERIMENT_CONFIG_SCHEMA_VERSION,
            endpoint: DEFAULT_LOCAL_ENDPOINT.to_owned(),
            models: Vec::new(),
            tasks: crate::agent_benchmark::BENCHMARK_TASKS
                .iter()
                .map(|task| task.id.to_owned())
                .collect(),
            repeat_count: 1,
            quality: QualityPreference::Balanced,
            execution_order: BenchmarkExecutionOrder::Deterministic,
            stop_on_failure: false,
            output_dir: PathBuf::from("benchmark-results"),
        }
    }
}

impl BenchmarkExperimentConfig {
    fn load(path: &Path) -> Result<Self, String> {
        let bytes = fs::read(path).map_err(|error| format!("{}: {error}", path.display()))?;
        let config = serde_json::from_slice::<Self>(&bytes)
            .map_err(|error| format!("{}: {error}", path.display()))?;
        config.validate()?;
        Ok(config)
    }

    fn validate(&self) -> Result<(), String> {
        if self.schema_version != EXPERIMENT_CONFIG_SCHEMA_VERSION {
            return Err(format!(
                "unsupported benchmark experiment config schema {}",
                self.schema_version
            ));
        }
        if self.endpoint.trim().is_empty() {
            return Err("benchmark endpoint must be non-empty".to_owned());
        }
        if self.models.is_empty() {
            return Err("benchmark experiment requires at least one exact model id".to_owned());
        }
        if self.models.len() > 64 {
            return Err("benchmark experiment supports at most 64 models per suite".to_owned());
        }
        if self.repeat_count == 0 || self.repeat_count > 100 {
            return Err("benchmark repeat_count must be between 1 and 100".to_owned());
        }
        if self.output_dir.as_os_str().is_empty() {
            return Err("benchmark output_dir must be non-empty".to_owned());
        }
        let mut model_ids = BTreeSet::new();
        for model in &self.models {
            let model = model.trim();
            if model.is_empty() {
                return Err("benchmark model ids must be non-empty".to_owned());
            }
            if !model_ids.insert(model.to_owned()) {
                return Err(format!("duplicate benchmark model `{model}`"));
            }
        }
        if self.tasks.is_empty() {
            return Err("benchmark experiment requires at least one task".to_owned());
        }
        let mut task_ids = BTreeSet::new();
        for task in &self.tasks {
            if benchmark_task(task).is_none() {
                return Err(format!("unknown benchmark task `{task}`"));
            }
            if !task_ids.insert(task.clone()) {
                return Err(format!("duplicate benchmark task `{task}`"));
            }
        }
        Ok(())
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct BenchmarkScheduledRun {
    pub(crate) ordinal: u64,
    pub(crate) model_id: String,
    pub(crate) task_id: String,
    pub(crate) repetition: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub(crate) struct BenchmarkRunSpec {
    pub(crate) schema_version: u32,
    pub(crate) runner_version: String,
    pub(crate) experiment_id: String,
    pub(crate) engine_commit_sha: String,
    pub(crate) corpus_version: String,
    pub(crate) harness_version: String,
    pub(crate) fixture_version: String,
    pub(crate) fixture_fingerprint: String,
    pub(crate) endpoint: String,
    pub(crate) model_id: String,
    pub(crate) task_id: String,
    pub(crate) quality: QualityPreference,
    pub(crate) ordinal: u64,
    pub(crate) total_runs: u64,
    pub(crate) repetition: u32,
    pub(crate) fixture_root: PathBuf,
    pub(crate) result_path: PathBuf,
}

impl BenchmarkRunSpec {
    pub(crate) fn load(path: &Path) -> Result<Self, String> {
        let bytes = fs::read(path).map_err(|error| format!("{}: {error}", path.display()))?;
        let spec = serde_json::from_slice::<Self>(&bytes)
            .map_err(|error| format!("{}: {error}", path.display()))?;
        spec.validate()?;
        Ok(spec)
    }

    fn validate(&self) -> Result<(), String> {
        if self.schema_version != EXPERIMENT_RESULT_SCHEMA_VERSION {
            return Err(format!("unsupported benchmark run spec schema {}", self.schema_version));
        }
        if self.runner_version != BENCHMARK_EXPERIMENT_RUNNER_VERSION
            || self.corpus_version != BENCHMARK_CORPUS_VERSION
            || self.harness_version != BENCHMARK_HARNESS_VERSION
            || self.fixture_version != BENCHMARK_FIXTURE_VERSION
        {
            return Err("benchmark run spec version identity does not match this Editor".to_owned());
        }
        if self.engine_commit_sha.len() != 40
            || !self.engine_commit_sha.chars().all(|character| character.is_ascii_hexdigit())
        {
            return Err("benchmark run spec requires an exact 40-character GameEngine commit SHA".to_owned());
        }
        if benchmark_task(&self.task_id).is_none() {
            return Err(format!("unknown benchmark task `{}`", self.task_id));
        }
        if self.model_id.trim().is_empty() || self.endpoint.trim().is_empty() {
            return Err("benchmark run spec requires an exact model id and endpoint".to_owned());
        }
        if self.fixture_fingerprint != fixture_fingerprint(&self.task_id)? {
            return Err("benchmark fixture fingerprint does not match the versioned task template".to_owned());
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub(crate) struct BenchmarkRunEvidence {
    #[serde(default)]
    pub(crate) agent_run_id: Option<String>,
    #[serde(default)]
    pub(crate) validation_attempt_ids: Vec<String>,
    #[serde(default)]
    pub(crate) frame_artifact_ids: Vec<String>,
    #[serde(default)]
    pub(crate) runtime_events: Vec<String>,
    #[serde(default)]
    pub(crate) visual_evaluation: Option<bool>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub(crate) struct BenchmarkRunResult {
    pub(crate) schema_version: u32,
    pub(crate) spec: BenchmarkRunSpec,
    pub(crate) outcome: BenchmarkRunOutcome,
    #[serde(default)]
    pub(crate) failure_kind: Option<BenchmarkFailureKind>,
    pub(crate) message: String,
    #[serde(default)]
    pub(crate) record: Option<BenchmarkRecord>,
    #[serde(default)]
    pub(crate) evidence: BenchmarkRunEvidence,
}

impl BenchmarkRunResult {
    pub(crate) fn write(&self) -> Result<(), String> {
        if let Some(parent) = self.spec.result_path.parent() {
            fs::create_dir_all(parent).map_err(|error| error.to_string())?;
        }
        let bytes = serde_json::to_vec_pretty(self).map_err(|error| error.to_string())?;
        fs::write(&self.spec.result_path, bytes).map_err(|error| error.to_string())
    }

    fn failed_child(spec: BenchmarkRunSpec, status: Option<ExitStatus>, message: String) -> Self {
        let detail = status
            .and_then(|status| status.code())
            .map(|code| format!("child exited with code {code}; {message}"))
            .unwrap_or(message);
        Self {
            schema_version: EXPERIMENT_RESULT_SCHEMA_VERSION,
            spec,
            outcome: BenchmarkRunOutcome::Failed,
            failure_kind: Some(BenchmarkFailureKind::ChildProcess),
            message: detail,
            record: None,
            evidence: BenchmarkRunEvidence::default(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
