#[derive(Debug, Clone)]
pub(crate) struct BenchmarkScenario {
    pub(crate) question: Option<String>,
    pub(crate) proposal: AgentProposal,
    pub(crate) requires_visual_input: bool,
    pub(crate) expected_runtime_inputs: Vec<serde_json::Value>,
}

pub(crate) fn scenario_for_task(task_id: &str) -> Result<BenchmarkScenario, String> {
    let task = benchmark_task(task_id).ok_or_else(|| format!("unknown benchmark task `{task_id}`"))?;
    let mut proposal = AgentProposal::default();
    proposal.goal = match task.kind {
        BenchmarkTaskKind::ReadQuestion => "Answer a repository-owned fixture question with provenance.",
        BenchmarkTaskKind::ProjectInspection => "Inspect the repository-owned benchmark project through authoritative read tools.",
        BenchmarkTaskKind::CodeImplementation => "Implement the benchmark_value contract in game/src/benchmark_task.rs.",
        BenchmarkTaskKind::TypedAuthoringMutation => "Create the requested entity through GameEngine typed authoring only.",
        BenchmarkTaskKind::ValidationRepair => "Observe the seeded validation failure, repair it, and revalidate.",
        BenchmarkTaskKind::RuntimeInteraction => "Launch normal Play and execute the required virtual input interaction.",
        BenchmarkTaskKind::VisualEvaluation => "Launch normal Play, capture Game View, and evaluate the actual image.",
    }
    .to_owned();
    proposal.requirements = vec![
        "Use only the repository-owned benchmark fixture; never inspect or upload another project.".to_owned(),
        "Do not bypass GameEngine permission, ownership, typed authoring, validation, Play, or frame-capture paths.".to_owned(),
    ];
    proposal.acceptance_criteria = task
        .completion_criteria
        .iter()
        .map(|criterion| (*criterion).to_owned())
        .collect();

    let mut question = None;
    let mut expected_runtime_inputs = Vec::new();
    let requires_visual_input = task.kind == BenchmarkTaskKind::VisualEvaluation;
    match task.kind {
        BenchmarkTaskKind::ReadQuestion => {
            question = Some(
                "Using retrieved repository/project evidence only, state the benchmark fixture project name and the required benchmark_value target. Include provenance for both facts."
                    .to_owned(),
            );
        }
        BenchmarkTaskKind::ProjectInspection => {
            proposal.requirements.push(
                "Use project/scene inspection tools and verify the project is `GameEngine Agent Benchmark Fixture` with zero initial authoring entities. Do not mutate."
                    .to_owned(),
            );
        }
        BenchmarkTaskKind::CodeImplementation => {
            proposal.planned_code_changes = vec!["game/src/benchmark_task.rs".to_owned()];
            proposal.work_claims.insert(AgentWorkClaim::code_path("game/src/benchmark_task.rs"));
            proposal.validation_plan = vec!["source validation".to_owned()];
            proposal.requirements.push(
                "Change benchmark_value() from 41 to 42, preserve the test, then use managed source validation."
                    .to_owned(),
            );
        }
        BenchmarkTaskKind::TypedAuthoringMutation => {
            proposal.planned_project_changes = vec![
                "Create one entity named BenchmarkAgentEntity in assets/scenes/main.scene.json through typed MCP authoring."
                    .to_owned(),
            ];
            proposal.work_claims.insert(AgentWorkClaim::authoring_document(
                "assets/scenes/main.scene.json",
            ));
            proposal.requirements.push(
                "Raw workspace/file editing is forbidden. Use the authoritative typed authoring surface and validate the resulting authoring state."
                    .to_owned(),
            );
        }
        BenchmarkTaskKind::ValidationRepair => {
            proposal.planned_code_changes = vec!["game/src/benchmark_task.rs".to_owned()];
            proposal.work_claims.insert(AgentWorkClaim::code_path("game/src/benchmark_task.rs"));
            proposal.validation_plan = vec!["source validation".to_owned()];
            proposal.requirements.push(
                "Do not modify source before the first managed validation attempt. Return ready_for_validation, observe the seeded failing test, then repair benchmark_value() to 42 and revalidate."
                    .to_owned(),
            );
        }
        BenchmarkTaskKind::RuntimeInteraction => {
            proposal.playtest_plan = vec![
                "Launch normal Editor Play and queue the exact Space press/release virtual input sequence."
                    .to_owned(),
            ];
            proposal.requested_capabilities.insert(AgentCapability::RuntimeLaunch);
            proposal.requested_capabilities.insert(AgentCapability::RuntimeInputControl);
            expected_runtime_inputs = benchmark_runtime_inputs();
        }
        BenchmarkTaskKind::VisualEvaluation => {
            proposal.playtest_plan = vec![
                "Launch normal Editor Play, queue the exact Space press/release virtual input sequence, capture Game View, then evaluate the attached frame."
                    .to_owned(),
            ];
            proposal.requested_capabilities.insert(AgentCapability::RuntimeLaunch);
            proposal.requested_capabilities.insert(AgentCapability::RuntimeInputControl);
            proposal.requested_capabilities.insert(AgentCapability::FrameCapture);
            expected_runtime_inputs = benchmark_runtime_inputs();
        }
    }

    Ok(BenchmarkScenario {
        question,
        proposal,
        requires_visual_input,
        expected_runtime_inputs,
    })
}

fn benchmark_runtime_inputs() -> Vec<serde_json::Value> {
    vec![
        serde_json::json!({"keyboard": {"key": "Space", "pressed": true}}),
        serde_json::json!({"keyboard": {"key": "Space", "pressed": false}}),
    ]
}

pub(crate) fn run_experiment_cli(config_path: &Path) -> Result<(), String> {
    let config = BenchmarkExperimentConfig::load(config_path)?;
    let (engine_root, engine_commit_sha) = exact_engine_checkout()?;
    let experiment_id = format!("experiment-{}-{}", unix_ms(), std::process::id());
    let output_dir = absolute_output_dir(&config.output_dir)?;
    fs::create_dir_all(&output_dir).map_err(|error| error.to_string())?;
    let schedule = build_schedule(&config);
    let total_runs = schedule.len() as u64;
    let executable = std::env::current_exe().map_err(|error| error.to_string())?;
    let mut results = Vec::new();

    for scheduled in schedule {
        let run_dir = output_dir.join(format!("run-{:04}", scheduled.ordinal));
        let fixture_root = run_dir.join("fixture");
        prepare_fixture(
            &fixture_root,
            &engine_root,
            &engine_commit_sha,
            &scheduled.task_id,
        )?;
        let result_path = run_dir.join("result.json");
        let spec = BenchmarkRunSpec {
            schema_version: EXPERIMENT_RESULT_SCHEMA_VERSION,
            runner_version: BENCHMARK_EXPERIMENT_RUNNER_VERSION.to_owned(),
            experiment_id: experiment_id.clone(),
            engine_commit_sha: engine_commit_sha.clone(),
            corpus_version: BENCHMARK_CORPUS_VERSION.to_owned(),
            harness_version: BENCHMARK_HARNESS_VERSION.to_owned(),
            fixture_version: BENCHMARK_FIXTURE_VERSION.to_owned(),
            fixture_fingerprint: fixture_fingerprint(&scheduled.task_id)?,
            endpoint: config.endpoint.clone(),
            model_id: scheduled.model_id.clone(),
            task_id: scheduled.task_id.clone(),
            quality: config.quality,
            ordinal: scheduled.ordinal,
            total_runs,
            repetition: scheduled.repetition,
            fixture_root: fixture_root.clone(),
            result_path: result_path.clone(),
        };
        let spec_path = run_dir.join("run-spec.json");
        fs::create_dir_all(&run_dir).map_err(|error| error.to_string())?;
        fs::write(
            &spec_path,
            serde_json::to_vec_pretty(&spec).map_err(|error| error.to_string())?,
        )
        .map_err(|error| error.to_string())?;

        let status = Command::new(&executable)
            .arg("--project")
            .arg(&fixture_root)
            .arg("--benchmark-run-spec")
            .arg(&spec_path)
            .current_dir(&engine_root)
            .status();
        let result = match status {
            Ok(status) if result_path.is_file() => {
                let bytes = fs::read(&result_path).map_err(|error| error.to_string())?;
                serde_json::from_slice::<BenchmarkRunResult>(&bytes)
                    .map_err(|error| format!("{}: {error}", result_path.display()))?
            }
            Ok(status) => {
                let result = BenchmarkRunResult::failed_child(
                    spec,
                    Some(status),
                    "benchmark child exited without a result record".to_owned(),
                );
                result.write()?;
                result
            }
            Err(error) => {
                let result = BenchmarkRunResult::failed_child(
                    spec,
                    None,
                    format!("could not spawn benchmark child: {error}"),
                );
                result.write()?;
                result
            }
        };
        let stop = config.stop_on_failure && result.outcome != BenchmarkRunOutcome::Passed;
        results.push(result);
        if stop {
            break;
        }
    }

    let summary = summarize_results(
        &experiment_id,
        &engine_commit_sha,
        total_runs,
        &results,
    );
    fs::write(
        output_dir.join("summary.json"),
        serde_json::to_vec_pretty(&summary).map_err(|error| error.to_string())?,
    )
    .map_err(|error| error.to_string())?;
    Ok(())
}

fn build_schedule(config: &BenchmarkExperimentConfig) -> Vec<BenchmarkScheduledRun> {
    let mut schedule = Vec::new();
    for repetition in 0..config.repeat_count {
        for task in &config.tasks {
            for model in &config.models {
                schedule.push(BenchmarkScheduledRun {
                    ordinal: 0,
                    model_id: model.trim().to_owned(),
                    task_id: task.clone(),
                    repetition,
                });
            }
        }
    }
    if let BenchmarkExecutionOrder::SeededRandom { seed } = config.execution_order {
        schedule.sort_by_key(|run| stable_order_key(seed, run));
    }
    for (index, run) in schedule.iter_mut().enumerate() {
        run.ordinal = index as u64 + 1;
    }
    schedule
}

fn stable_order_key(seed: u64, run: &BenchmarkScheduledRun) -> (u64, String, String, u32) {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64 ^ seed;
    for byte in run
        .model_id
        .bytes()
        .chain(run.task_id.bytes())
        .chain(run.repetition.to_le_bytes())
    {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    (hash, run.model_id.clone(), run.task_id.clone(), run.repetition)
}

fn fixture_fingerprint(task_id: &str) -> Result<String, String> {
    let source = benchmark_task_source(task_id)?;
    let canonical = format!(
        "{}\n{}\n{}\n{}\n{}",
        BENCHMARK_FIXTURE_VERSION,
        task_id,
        benchmark_fixture_readme(),
        benchmark_scene_json(),
        source
    );
    Ok(format!("fnv1a64-{:016x}", stable_hash(canonical.as_bytes())))
}

fn stable_hash(bytes: &[u8]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn prepare_fixture(
    root: &Path,
    engine_root: &Path,
    engine_commit_sha: &str,
    task_id: &str,
) -> Result<(), String> {
    reset_fixture_root(root)?;
    fs::create_dir_all(root.join("assets/scenes")).map_err(|error| error.to_string())?;
    fs::create_dir_all(root.join("game/src")).map_err(|error| error.to_string())?;
    let marker = serde_json::json!({
        "schema_version": 1,
        "fixture_version": BENCHMARK_FIXTURE_VERSION,
        "engine_commit_sha": engine_commit_sha,
        "task_id": task_id,
        "fixture_fingerprint": fixture_fingerprint(task_id)?,
    });
    write_text(
        &root.join(FIXTURE_MARKER_FILE),
        &serde_json::to_string_pretty(&marker).map_err(|error| error.to_string())?,
    )?;
    write_text(
        &root.join("project.json"),
        "{\n  \"schema_version\": 2,\n  \"project_id\": \"project_01J00000000000000000000000\",\n  \"name\": \"GameEngine Agent Benchmark Fixture\",\n  \"engine_version\": \"0.1.0\"\n}\n",
    )?;
    write_text(&root.join("README.md"), benchmark_fixture_readme())?;
    write_text(&root.join("assets/scenes/main.scene.json"), benchmark_scene_json())?;
    let engine_path = engine_root
        .join("crates/engine")
        .to_string_lossy()
        .replace('\\', "/")
        .replace('\'', "\\'");
    write_text(
        &root.join("game/Cargo.toml"),
        &format!(
            "[package]\nname = \"gameengine-agent-benchmark-fixture\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[lib]\ncrate-type = [\"cdylib\"]\n\n[dependencies]\nengine = {{ path = \"{engine_path}\" }}\n"
        ),
    )?;
    write_text(
        &root.join("game/src/lib.rs"),
        "//! Repository-owned ADR 0142 benchmark fixture game module.\n\nmod benchmark_task;\ninclude!(\"project_modules.rs\");\n\nengine::export_game_module!();\n",
    )?;
    write_text(
        &root.join("game/src/project_modules.rs"),
        "// Deterministic empty generated module index for the benchmark fixture.\npub mod components {}\npub mod resources {}\npub mod shared {}\npub mod systems {}\n",
    )?;
    write_text(
        &root.join("game/src/benchmark_task.rs"),
        benchmark_task_source(task_id)?,
    )?;
    Ok(())
}

fn reset_fixture_root(root: &Path) -> Result<(), String> {
    if !root.exists() {
        return Ok(());
    }
    if !root.is_dir() {
        return Err(format!("benchmark fixture path `{}` is not a directory", root.display()));
    }
    let marker_path = root.join(FIXTURE_MARKER_FILE);
    let marker = fs::read_to_string(&marker_path).map_err(|_| {
        format!(
            "refusing to reset unmarked directory `{}`; benchmark fixtures are the only removable roots",
            root.display()
        )
    })?;
    let marker: serde_json::Value = serde_json::from_str(&marker).map_err(|error| error.to_string())?;
    if marker.get("fixture_version").and_then(serde_json::Value::as_str)
        != Some(BENCHMARK_FIXTURE_VERSION)
    {
        return Err(format!("refusing to reset foreign fixture root `{}`", root.display()));
    }
    fs::remove_dir_all(root).map_err(|error| error.to_string())
}

