fn write_text(path: &Path, text: &str) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|error| error.to_string())?;
    }
    fs::write(path, text.as_bytes()).map_err(|error| format!("{}: {error}", path.display()))
}

fn exact_engine_checkout() -> Result<(PathBuf, String), String> {
    let root = git_output(&["rev-parse", "--show-toplevel"], None)?;
    let root = PathBuf::from(root.trim());
    let status = git_output(&["status", "--porcelain", "--untracked-files=no"], Some(&root))?;
    if !status.trim().is_empty() {
        return Err("benchmark experiments require a clean tracked GameEngine checkout so the binary can be attributed to an exact commit".to_owned());
    }
    let sha = git_output(&["rev-parse", "HEAD"], Some(&root))?;
    let sha = sha.trim().to_owned();
    if sha.len() != 40 || !sha.chars().all(|character| character.is_ascii_hexdigit()) {
        return Err("git did not return an exact 40-character GameEngine commit SHA".to_owned());
    }
    Ok((root, sha))
}

fn git_output(args: &[&str], current_dir: Option<&Path>) -> Result<String, String> {
    let mut command = Command::new("git");
    command.args(args);
    if let Some(current_dir) = current_dir {
        command.current_dir(current_dir);
    }
    let output = command.output().map_err(|error| format!("could not run git: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "git {} failed: {}",
            args.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    String::from_utf8(output.stdout).map_err(|error| error.to_string())
}

fn absolute_output_dir(path: &Path) -> Result<PathBuf, String> {
    if path.is_absolute() {
        return Ok(path.to_path_buf());
    }
    std::env::current_dir()
        .map(|current| current.join(path))
        .map_err(|error| error.to_string())
}

fn summarize_results(
    experiment_id: &str,
    engine_commit_sha: &str,
    planned_runs: u64,
    results: &[BenchmarkRunResult],
) -> BenchmarkExperimentSummary {
    let mut grouped = BTreeMap::<String, Vec<&BenchmarkRunResult>>::new();
    for result in results {
        grouped.entry(result.spec.model_id.clone()).or_default().push(result);
    }
    let models = grouped
        .into_iter()
        .map(|(model_id, rows)| summarize_model(model_id, &rows))
        .collect();
    BenchmarkExperimentSummary {
        schema_version: EXPERIMENT_RESULT_SCHEMA_VERSION,
        runner_version: BENCHMARK_EXPERIMENT_RUNNER_VERSION.to_owned(),
        experiment_id: experiment_id.to_owned(),
        engine_commit_sha: engine_commit_sha.to_owned(),
        fixture_version: BENCHMARK_FIXTURE_VERSION.to_owned(),
        planned_runs,
        completed_runs: results.len() as u64,
        models,
    }
}

fn summarize_model(model_id: String, rows: &[&BenchmarkRunResult]) -> BenchmarkModelSummary {
    let records = rows.iter().filter_map(|row| row.record.as_ref()).collect::<Vec<_>>();
    BenchmarkModelSummary {
        model_id,
        runs: rows.len() as u64,
        passed: rows.iter().filter(|row| row.outcome == BenchmarkRunOutcome::Passed).count() as u64,
        failed: rows.iter().filter(|row| row.outcome == BenchmarkRunOutcome::Failed).count() as u64,
        unavailable: rows
            .iter()
            .filter(|row| row.outcome == BenchmarkRunOutcome::Unavailable)
            .count() as u64,
        completion_gate_passes: records
            .iter()
            .filter(|record| record.metrics.completion_success == TelemetryValue::Measured(true))
            .count() as u64,
        model_turns: sum_measured(&records, |record| &record.metrics.model_turns),
        tool_calls: sum_measured(&records, |record| &record.metrics.tool_calls),
        invalid_tool_calls: sum_measured(&records, |record| &record.metrics.invalid_or_failed_tool_calls),
        repair_loops: sum_measured(&records, |record| &record.metrics.repair_loops),
        validation_attempts: sum_measured(&records, |record| &record.metrics.validation_attempts),
        elapsed_ms: sum_measured(&records, |record| &record.metrics.elapsed_ms),
        load_latency_ms: sum_measured(&records, |record| &record.metrics.load_latency_ms),
        response_tokens: sum_measured(&records, |record| &record.metrics.response_tokens),
        generation_tokens_per_second_milli: average_measured(
            &records,
            |record| &record.metrics.generation_tokens_per_second_milli,
        ),
        oom_failures: sum_measured(&records, |record| &record.metrics.oom_failures),
        human_interventions: sum_measured(&records, |record| &record.metrics.human_interventions),
        visual_successes: rows
            .iter()
            .filter(|row| row.evidence.visual_evaluation == Some(true))
            .count() as u64,
        runtime_successes: rows
            .iter()
            .filter(|row| !row.evidence.runtime_events.is_empty() && row.outcome == BenchmarkRunOutcome::Passed)
            .count() as u64,
    }
}

fn sum_measured(
    records: &[&BenchmarkRecord],
    select: impl Fn(&BenchmarkRecord) -> &TelemetryValue<u64>,
) -> TelemetryValue<u64> {
    let mut total = 0_u64;
    for record in records {
        let TelemetryValue::Measured(value) = select(record) else {
            return TelemetryValue::Unavailable;
        };
        total = total.saturating_add(*value);
    }
    if records.is_empty() {
        TelemetryValue::Unavailable
    } else {
        TelemetryValue::Measured(total)
    }
}

fn average_measured(
    records: &[&BenchmarkRecord],
    select: impl Fn(&BenchmarkRecord) -> &TelemetryValue<u64>,
) -> TelemetryValue<u64> {
    let TelemetryValue::Measured(total) = sum_measured(records, select) else {
        return TelemetryValue::Unavailable;
    };
    TelemetryValue::Measured(total / records.len() as u64)
}

fn unix_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
        .min(u128::from(u64::MAX)) as u64
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(models: usize, repeats: u32) -> BenchmarkExperimentConfig {
        BenchmarkExperimentConfig {
            models: (0..models).map(|index| format!("model-{index}")).collect(),
            tasks: crate::agent_benchmark::BENCHMARK_TASKS
                .iter()
                .map(|task| task.id.to_owned())
                .collect(),
            repeat_count: repeats,
            ..BenchmarkExperimentConfig::default()
        }
    }

    #[test]
    fn four_models_seven_tasks_three_repetitions_schedule_eighty_four_runs() {
        let schedule = build_schedule(&config(4, 3));
        assert_eq!(schedule.len(), 84);
        assert_eq!(schedule.first().map(|run| run.ordinal), Some(1));
        assert_eq!(schedule.last().map(|run| run.ordinal), Some(84));
    }

    #[test]
    fn seeded_order_is_stable_and_preserves_every_run() {
        let mut left = config(4, 3);
        left.execution_order = BenchmarkExecutionOrder::SeededRandom { seed: 42 };
        let right = left.clone();
        assert_eq!(build_schedule(&left), build_schedule(&right));
        let mut changed = left.clone();
        changed.execution_order = BenchmarkExecutionOrder::SeededRandom { seed: 43 };
        assert_ne!(build_schedule(&left), build_schedule(&changed));
        assert_eq!(build_schedule(&changed).len(), 84);
    }

    #[test]
    fn fixture_reset_removes_previous_run_state_and_refuses_unmarked_directories() {
        let temp = tempfile::tempdir().expect("tempdir");
        let fixture = temp.path().join("fixture");
        fs::create_dir_all(&fixture).expect("fixture");
        fs::write(fixture.join("private.txt"), b"do not delete").expect("foreign file");
        assert!(reset_fixture_root(&fixture).is_err());

        fs::write(
            fixture.join(FIXTURE_MARKER_FILE),
            format!("{{\"fixture_version\":\"{}\"}}", BENCHMARK_FIXTURE_VERSION),
        )
        .expect("marker");
        fs::write(fixture.join("previous-run.txt"), b"dirty").expect("run state");
        reset_fixture_root(&fixture).expect("reset marked fixture");
        assert!(!fixture.exists());
    }

    #[test]
    fn fixture_fingerprint_is_task_versioned_and_stable() {
        let read = fixture_fingerprint("read_question_v1").expect("read fingerprint");
        assert_eq!(read, fixture_fingerprint("read_question_v1").expect("stable fingerprint"));
        assert_ne!(
            read,
            fixture_fingerprint("code_implementation_v1").expect("code fingerprint")
        );
    }

    #[test]
    fn visual_scenario_requires_real_image_input_and_runtime_uses_virtual_input() {
        let visual = scenario_for_task("visual_evaluation_v1").expect("visual scenario");
        assert!(visual.requires_visual_input);
        assert_eq!(visual.expected_runtime_inputs.len(), 2);
        assert!(visual.proposal.requested_capabilities.contains(&AgentCapability::FrameCapture));

        let runtime = scenario_for_task("runtime_interaction_v1").expect("runtime scenario");
        assert!(!runtime.requires_visual_input);
        assert_eq!(runtime.expected_runtime_inputs.len(), 2);
    }

    #[test]
    fn validation_repair_fixture_starts_failing_and_requires_revalidation() {
        let source = benchmark_task_source("validation_repair_v1").expect("repair source");
        assert!(source.contains("41"));
        assert!(source.contains("assert_eq!(benchmark_value(), 42)"));
        let scenario = scenario_for_task("validation_repair_v1").expect("repair scenario");
        assert_eq!(scenario.proposal.validation_plan, vec!["source validation"]);
    }

    #[test]
    fn arbitrary_exact_model_names_are_not_hard_coded() {
        let mut config = config(1, 1);
        config.models = vec![
            "qwen3.8-custom:27b-q4".to_owned(),
            "gemma-custom:latest".to_owned(),
        ];
        config.validate().expect("arbitrary model ids");
        let schedule = build_schedule(&config);
        assert!(schedule.iter().any(|run| run.model_id == "qwen3.8-custom:27b-q4"));
        assert!(schedule.iter().any(|run| run.model_id == "gemma-custom:latest"));
    }
}
